const css=`@font-face{font-family:'CafeBody';src:url(data:font/ttf;base64,) format('truetype');font-weight:400;}@font-face{font-family:'CafeBody';src:url(data:font/ttf;base64,) format('truetype');font-weight:700;}@font-face{font-family:'CafeHeading';src:url(data:font/ttf;base64,) format('truetype');font-weight:700;}@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;font:10.4pt/1.45 CafeBody,Arial,sans-serif;color:#303870;background:#f4ede2}.page{height:297mm;width:210mm;padding:17mm 18mm 16mm;position:relative;break-after:page;overflow:hidden}.page:last-child{break-after:auto}.running{font-size:8pt;color:#303870;margin-bottom:12mm;letter-spacing:1px}h1{font-family:CafeHeading,Arial,sans-serif;font-size:21.5pt;text-transform:uppercase;letter-spacing:0;line-height:1.05;margin:13mm 0 6mm;color:#303870}h2{font-family:CafeHeading,Arial,sans-serif;font-size:18.2pt;text-transform:uppercase;line-height:1.2;letter-spacing:0;margin:0 0 7mm;color:#303870}h3{font-size:13.3pt;margin:5mm 0 2mm;color:#303870}p{margin:2.5mm 0;orphans:3;widows:3}.cover-label{font-size:9pt;letter-spacing:2px;font-weight:bold;margin:6mm 0}.cover-sub{font-size:20pt;line-height:1.2;margin-bottom:10mm}.page:first-child h3{margin-top:11mm}table{border-collapse:collapse;width:100%;font-size:8.4pt;line-height:1.34;margin:4mm 0}th,td{text-align:left;padding:2.7mm 2.1mm;border-bottom:1px solid #dbe3f0;vertical-align:top}th{background:#e6dfd4;color:#303870}th:first-child{width:18%}tr{break-inside:avoid}aside{background:#e6dfd4;color:#303870;padding:3.5mm;font-size:9pt;margin-top:5mm;border-radius:2mm}figure{margin:4mm 0}figure img{display:block;max-width:100%;object-fit:contain;margin:auto}figcaption{font-size:8pt;color:#303870;margin-top:2mm}.two{display:flex;gap:6mm;align-items:flex-start}.two figure{width:50%}.two img{width:100%}.foot{position:absolute;bottom:10mm;left:18mm;right:18mm;display:flex;justify-content:space-between;font-size:8pt;color:#303870}svg{width:100%;height:auto;max-height:115mm}b{font-weight:700}`;
const html=`<!doctype html><html lang="en"><meta charset="utf-8"><title>DashFood Final ICT Project</title><style>${css}</style><body>${pages.map((s,i)=>`<section class="page"><div class="running">DASHFOOD / SE-2622 / FINAL ICT PROJECT</div>${i===0?`<h1>${s.title}</h1>`:`<h2>${s.title}</h2>`}${s.body}<div class="foot"><span>8 November 2026</span><span>${String(i+1).padStart(2,'0')} / ${pages.length}</span></div></section>`).join('')}</body></html>`;
mkdirSync('output/final',{recursive:true});writeFileSync('docs/FINAL_REPORT.html',html);
const browser=await chromium.launch({channel:'chrome',headless:true});
try{
 const page=await browser.newPage();await page.goto(pathToFileURL(path.resolve('docs/FINAL_REPORT.html')).href);await page.evaluate(()=>Promise.all([...document.images].map(i=>i.decode())));
 const overflow=await page.locator('.page').evaluateAll(nodes=>nodes.map((n,i)=>({page:i+1,overflow:n.scrollHeight>n.clientHeight+1,lastContent:n.children[n.children.length-2]?.getBoundingClientRect().bottom,footer:n.lastElementChild.getBoundingClientRect().top})).filter(r=>r.overflow||r.lastContent>r.footer-8));
 if(overflow.length)throw new Error('Report layout exceeds safe area: '+JSON.stringify(overflow));
 await page.pdf({path:'output/final/SE2622_DashFood_ICT_FinalProject.pdf',format:'A4',printBackground:true,preferCSSPageSize:true});
 writeFileSync('output/evidence/report-validation.json',JSON.stringify({pages:pages.length,executiveWords:wordCount,overflow},null,2));console.log('Created '+pages.length+' pages; executive summary '+wordCount+' words.');
}finally{await browser.close();}
